# Search for a canonical complete mapping in 3-D tiles: g in the group generated by column flips
# R_a(x) = x with x_a -> t_a(x) - x_a (involution of D).  Test bijectivity of x -> phi(g x) + phi(tau x) on all tiles.
import sys, itertools
import numpy as np
sys.path.insert(0, 'src'); sys.path.insert(0, 'src/scratch')
from exp_cl_tiling import downsets
from corner_bij import tops
d = int(sys.argv[1]); M0, M1 = int(sys.argv[2]), int(sys.argv[3]); L = int(sys.argv[4])
words = [w for n in range(0, L + 1) for w in itertools.product(range(d), repeat=n)
         if all(w[i] != w[i+1] for i in range(len(w) - 1))]
res = {w: [0, 0] for w in words}
for m in range(M0, M1 + 1):
    P = np.array(np.meshgrid(*[np.arange(m)]*d, indexing='ij')).reshape(d, -1).T
    K = np.arange(m)
    for D in downsets(m, d):
        Dl = sorted(D)
        if any(all(n[a] == 0 for n in Dl) for a in range(d)): continue
        C = np.array(Dl); pos = (P @ C.T) % m
        ok = np.all(np.sort(pos, axis=1) == K, axis=1)
        if not ok.any(): continue
        tau = tops(D, d); Tau = np.array([tau[x] for x in Dl])
        def flip(x, a):
            y = list(x); y[a] = tau[x][a] - x[a]; return tuple(y)
        Pk = P[ok]; tpos = (Pk @ Tau.T) % m
        for w in words:
            img = []
            for x in Dl:
                y = x
                for a in w: y = flip(y, a)
                img.append(y)
            G = np.array(img)
            mv = ((Pk @ G.T) + tpos) % m
            bij = np.all(np.sort(mv, axis=1) == K, axis=1)
            res[w][0] += int(bij.sum()); res[w][1] += len(bij)
good = [(w, v) for w, v in res.items() if v[0] == v[1]]
print('always bijective:', good)
print('best:', sorted(res.items(), key=lambda kv: -kv[1][0]/kv[1][1])[:8])
